<text x="320" y="152" text-anchor="middle" font-size="13">{$t[3]}</text><text x="320" y="170" text-anchor="middle" font-size="13">{$t[4]}</text>
<path d="M410 115H452" stroke="#8A87B0" stroke-width="2" marker-end="url(#a)"/>
